"""Saved-only original body envelope, paved edge and right-pass observations."""
import argparse
import hashlib
import json
from pathlib import Path
from package_spec import CAMERA_NAMES
from right_pass_envelope import measure_data
def need(ok,message):
 if not ok:raise ValueError(message)
def source(root,name):
 path=root/name
 if not path.is_file() or path.is_symlink():raise ValueError('Missing required source: '+name)
 return path
def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def source_sealed_paved_edge_measurement(value):return value
def envelope_from_rows(history):
 rows=history['samples'];packet={'assignment_id':history['assignment_id'],'original_trace_id':history['reviewed_site_sha256'],'ego_actor_id':history['actor_ids'][0],'overtaken_actor_id':history['actor_ids'][1],'expected_pass':history['requested_right_pass'],'frames':[]}
 for row in rows:
  ego_s,ego_y=row['ego_body_s_bounds_m'],row['ego_body_y_bounds_m'];target_s,target_y=row['target_body_s_bounds_m'],row['target_body_y_bounds_m'];paved=row['paved_y_bounds_m']
  packet['frames'].append({'time_s':row['time_s'],'ego_left_m':ego_y[0],'ego_right_m':ego_y[1],'overtaken_left_m':target_y[0],'overtaken_right_m':target_y[1],'paved_left_m':paved[0],'paved_right_m':paved[1],'longitudinal_overlap':max(ego_s[0],target_s[0])<=min(ego_s[1],target_s[1]),'ego_ahead_of_overtaken':ego_s[0]>target_s[1]})
 return packet
def analyze(attempt):
 root=Path(attempt).resolve();config=json.loads(source(root,'config.json').read_text());case=config['selected_case_id'];receipt=json.loads(source(root,'original-source-receipt.json').read_text());diagnostic=receipt.get('diagnostic_fixture') is True
 need(receipt.get('source_kind')==('synthetic_diagnostic_fixture' if diagnostic else 'original_native_capture') and receipt.get('case_id')==case,'source provenance differs')
 for key,name in [('history_sha256','right-pass-history.json'),('trace_sha256','trace.jsonl'),('frame_map_sha256','video_frames.jsonl'),('envelope_sha256','right-pass-envelope.json'),('measurement_sha256','right-pass-measurement.json')]:need(receipt.get(key)==sha(source(root,name)),'sealed paved-edge source differs: '+name)
 history=json.loads(source(root,'right-pass-history.json').read_text());rows=history['samples'];traces=[json.loads(x) for x in source(root,'trace.jsonl').read_text().splitlines()];mapping=[json.loads(x) for x in source(root,'video_frames.jsonl').read_text().splitlines()]
 need(history.get('assignment_id')==config['assignment_id'] and history.get('case_id')==case and len(rows)==len(traces)==len(mapping) and len(rows)>=3 and len(history['actor_ids'])==2,'original case, actor or frame count differs')
 need(history.get('public_highway') is True and history.get('paved_surface_classified') is True and history.get('adjacent_surface_classified') is True and history.get('paved_surface_source') and history.get('paved_boundary_source') and history.get('connected_route_source'),'independent pavement classification/route source missing')
 for i,(row,trace,mapped) in enumerate(zip(rows,traces,mapping)):
  need(row['frame']==mapped['video_frame']==i and row['native_frame']==trace['frame']==mapped['native_frame']==mapped['carla_frame'] and row['time_s']==trace['time_s']==mapped['time_s'] and row['actor_ids']==history['actor_ids'] and abs(row['ego_speed_mps']-trace['speed_mps'])<1e-6,'original body/trace/video join differs')
  if not diagnostic:need(row['ego_position_xyz_m']==trace['position_m'],'original ego body pose differs from trace')
 envelope=json.loads(source(root,'right-pass-envelope.json').read_text());need(envelope==envelope_from_rows(history),'original body envelope differs from Native rows')
 measured=measure_data(envelope);need(json.loads(source(root,'right-pass-measurement.json').read_text())==measured,'saved body/pavement measurement differs')
 values={'paved_surface_classification':{'public_highway':True,'paved_surface_source':history['paved_surface_source'],'adjacent_surface_classified':True},'paved_edge_geometry':{'paved_boundary_source':history['paved_boundary_source'],'bounds_by_original_frame':[row['paved_y_bounds_m'] for row in rows]},'ego_and_overtaken_identity':{'actor_ids':history['actor_ids'],'driver_actor_id':history['driver_actor_id'],'overtaken_actor_source':history['overtaken_actor_source']},'ego_and_overtaken_body_envelopes':{'envelope_sha256':sha(root/'right-pass-envelope.json'),'frame_count':len(rows)},'right_side_pass_event':{'completed':measured['right_pass_completed'],'overlap_observations':measured['overlap_observations']},'actual_off_pavement_travel':{'observed':measured['actual_off_pavement_observed']},'physical_necessity_review':{'zero_clearance_fit_impossible':measured['zero_clearance_paved_fit_impossible_observed'],'legal_safe_alternative':'unresolved','review_limit':measured['review_limit']},'vehicle_motion':{'first_position_m':traces[0]['position_m'],'last_position_m':traces[-1]['position_m'],'maximum_speed_mps':max(row['ego_speed_mps'] for row in rows)}}
 sources={name:sha(source(root,name)) for name in ('right-pass-history.json','right-pass-envelope.json','original-source-receipt.json','trace.jsonl')}
 measurements={name:{'method':'source_sealed_paved_edge_measurement','value':source_sealed_paved_edge_measurement(value),'sources':sources} for name,value in values.items()}
 evidence=[]
 for channel in config['case']['recording_description']['channels']:
  name=channel['name'];path=root/('channel-'+name+'.jsonl');content=''.join(json.dumps({'time_s':row['time_s'],'value':row['ego_body_y_bounds_m'] if name in ('ego_and_overtaken_body_envelopes','actual_off_pavement_travel') else row['ego_body_s_bounds_m'] if name=='right_side_pass_event' else row['paved_y_bounds_m'] if name=='paved_edge_geometry' else row['ego_position_xyz_m'] if name=='vehicle_motion' else values[name]},sort_keys=True)+'\n' for row in rows)
  if path.exists():need(path.read_text()==content,'derived channel differs from saved source')
  else:path.write_text(content)
  evidence.append({'name':name,'unit':channel['unit'],'reference':path.name})
 context=root/'channel-reviewed_paved_edge_site.json';content=json.dumps({'reviewed_paved_edge_site':{'reviewed_site_sha256':history['reviewed_site_sha256'],'paved_surface_source':history['paved_surface_source'],'paved_boundary_source':history['paved_boundary_source']}},sort_keys=True)+'\n'
 if context.exists():need(context.read_text()==content,'reviewed paved-edge context differs')
 else:context.write_text(content)
 evidence.append({'name':'reviewed_paved_edge_site','unit':'source record','reference':context.name})
 from worker_exchange.native_output import physical_result,write_result
 result={'case_id':case,'measured_values':values,'target_checks':[{'target':'original right-side pass and off-pavement observations','requested':config['case']['requested_right_pass'],'measured':measured['right_pass_completed'],'method':'source-sealed body and paved-edge frames','tolerance':0,'matched':measured['right_pass_completed']==config['case']['requested_right_pass'],'physical_cause_confirmed':False,'cause_evidence':sources}],'setup_confirmed':False,'behavior_attempted':False,'maneuver_completed':False,'termination_reason':'saved physical and legal review pending','physical_failure_flags':['physical_acceptance_unverified'],'trace_reference':'trace.jsonl','video_references':[n+'.mkv' for n in CAMERA_NAMES],'video_frame_map_reference':'video_frames.jsonl','recording_description':config['case']['recording_description'],'recording_evidence':evidence,'realized_observables':{},'diagnostic_fixture':diagnostic,'physical_acceptance_claimed':False,'legal_verdict_claimed':False}
 result=physical_result(root,result);write_result(root,result)
 return {'format':'worker-analysis-report','case_id':case,'analysis_complete':True,'diagnostic_fixture':diagnostic,'physical_acceptance_claimed':False,'legal_verdict_claimed':False,'measurements':measurements,'physical_checks':result['physical_checks'],'realized_observables':result['realized_observables'],'limitations':['Actual off-pavement travel is separate from necessity; zero-clearance width alone cannot establish a safe lawful alternative.']}
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
 if args.output.exists():raise ValueError('retain prior analysis report')
 args.output.write_text(json.dumps(analyze(args.attempt),indent=2)+'\n')

"""Original-frame road-envelope measurements for passing on the right.

The operative word 'requires' is kept distinct from merely observing an
off-pavement path. Geometric fit is a lower bound, not a safety judgment.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


ASSIGNMENT = "testing__C182383__NRS-484B-210-3__motor_vehicle_driver"


def measure(path: str | Path) -> dict:
    path = Path(path)
    raw = path.read_bytes()
    packet = json.loads(raw)
    result = measure_data(packet)
    result["source"] = {"path": str(path), "sha256": hashlib.sha256(raw).hexdigest()}
    return result


def measure_data(packet: dict) -> dict:
    if packet.get("assignment_id") != ASSIGNMENT or not packet.get("original_trace_id"):
        raise ValueError("original assignment and trace identity required")
    if not packet.get("ego_actor_id") or not packet.get("overtaken_actor_id"):
        raise ValueError("original vehicle identities required")
    frames = packet.get("frames")
    if not isinstance(frames, list) or len(frames) < 3:
        raise ValueError("three original frames required")
    observations = []
    for i, f in enumerate(frames):
        for key in ("time_s", "ego_left_m", "ego_right_m", "overtaken_left_m", "overtaken_right_m", "paved_left_m", "paved_right_m"):
            v = f.get(key)
            if isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v):
                raise ValueError(f"frame {i}: original finite {key} required")
        if i and not 0 < f["time_s"] - frames[i - 1]["time_s"] <= 0.075:
            raise ValueError("ordered 20 Hz frames required")
        if not (f["paved_left_m"] < f["paved_right_m"] and f["ego_left_m"] < f["ego_right_m"] and f["overtaken_left_m"] < f["overtaken_right_m"]):
            raise ValueError("invalid original lateral envelopes")
        for key in ("longitudinal_overlap", "ego_ahead_of_overtaken"):
            if not isinstance(f.get(key), bool):
                raise ValueError(f"original {key} readback required")
        if f["longitudinal_overlap"]:
            width = f["ego_right_m"] - f["ego_left_m"]
            corridor = f["paved_right_m"] - f["overtaken_right_m"]
            observations.append({"frame_index": i,
                                 "ego_to_right_of_overtaken": f["ego_left_m"] >= f["overtaken_right_m"],
                                 "ego_body_off_pavement_m": max(0.0, f["ego_right_m"] - f["paved_right_m"]),
                                 "right_side_paved_corridor_m": corridor,
                                 "ego_body_width_m": width,
                                 "no_zero_clearance_fit_on_pavement": corridor < width})
    expected_pass = packet.get("expected_pass", True)
    if not isinstance(expected_pass, bool):
        raise ValueError("expected pass status must be source-typed")
    if not expected_pass:
        if frames[0]["ego_ahead_of_overtaken"] or frames[-1]["ego_ahead_of_overtaken"]:
            raise ValueError("no-pass control has completed overtaking")
        observations = []
    else:
        if not observations or not frames[-1]["ego_ahead_of_overtaken"] or frames[0]["ego_ahead_of_overtaken"]:
            raise ValueError("complete right-side pass event required")
        if not any(o["ego_to_right_of_overtaken"] for o in observations):
            raise ValueError("right-side overlap not observed")
    return {"assignment_id": ASSIGNMENT, "original_trace_id": packet["original_trace_id"],
            "right_pass_completed": expected_pass,
            "ego_actor_id": packet["ego_actor_id"], "overtaken_actor_id": packet["overtaken_actor_id"],
            "overlap_observations": observations,
            "actual_off_pavement_observed": any(o["ego_body_off_pavement_m"] > 0 for o in observations),
            "zero_clearance_paved_fit_impossible_observed": any(o["no_zero_clearance_fit_on_pavement"] for o in observations),
            "review_limit": "A zero-clearance body fit cannot establish a safe lawful alternative. Actual off-pavement motion alone does not establish that the movement required leaving the paved portion."}

"""Source-gated Native paved-edge pass corridor with separate actual and required facts."""
import math
from package_spec import AID
VARIANTS={'narrow_off_pavement':(False,True,True),'wide_on_pavement':(True,True,False),'wide_off_pavement':(True,True,True),'narrow_no_pass':(False,False,False)}
def number(v):
 if isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v):raise ValueError('finite numeric source fact required')
 return float(v)
def construct(site,case):
 suffix=case.removeprefix(AID+'__')
 if site.get('assignment_id')!=AID or site.get('case_id')!=case or suffix not in VARIANTS or site.get('source_kind')!='original_native_map_geometry' or site.get('reviewed_original_native_site') is not True:raise ValueError('exact reviewed Native paved-edge site required')
 for key in ('source_id','map_name','map_sha256','paved_surface_source','paved_boundary_source','connected_route_source','driver_actor_id','overtaken_actor_source'):
  if not site.get(key):raise ValueError('independent paved-edge/actor source missing: '+key)
 if site.get('public_highway') is not True or site.get('paved_surface_classified') is not True or site.get('adjacent_surface_classified') is not True:raise ValueError('public highway and classified paved/adjacent surfaces required')
 if site.get('map_lane_type_as_legal_pavement') is True:raise ValueError('map lane type cannot establish legal paved portion')
 fit,passed,off=VARIANTS[suffix]
 if (site.get('requested_zero_clearance_paved_fit'),site.get('requested_right_pass'),site.get('requested_off_pavement'))!=(fit,passed,off):raise ValueError('exact pass/pavement request differs')
 frame=site.get('road_frame')
 if not isinstance(frame,dict) or not frame.get('source_id') or any(not isinstance(frame.get(k),list) or len(frame[k])!=2 for k in ('origin_xy','station_axis_xy','left_axis_xy')):raise ValueError('source road frame required')
 for k in ('origin_xy','station_axis_xy','left_axis_xy'):
  for v in frame[k]:number(v)
 sections=site.get('cross_sections')
 if not isinstance(sections,list) or len(sections)<3:raise ValueError('continuous surveyed pass corridor required')
 stations=[]
 for section in sections:
  if section.get('source_kind')!='surveyed_original_native_pavement' or not section.get('source_ref') or section.get('connected_drivable_route') is not True:raise ValueError('source-surveyed connected paved/adjacent corridor required')
  stations.append(number(section.get('station_m')))
  lo,hi=section.get('paved_y_bounds_m',(None,None));number(lo);number(hi)
  if lo>=hi:raise ValueError('invalid paved bounds')
 if stations!=sorted(set(stations)) or stations[0]>-30 or stations[-1]<30 or max(b-a for a,b in zip(stations,stations[1:]))>5:raise ValueError('continuous 5m sampled corridor required')
 half=number(site.get('ego_body_half_width_m'));target_right=number(site.get('overtaken_right_edge_m'))
 if half<=0:raise ValueError('ego width required')
 available=min(section['paved_y_bounds_m'][1]-target_right for section in sections)
 observed_fit=available>=2*half
 if observed_fit is not fit:raise ValueError('requested zero-clearance body fit differs from surveyed width')
 control=site.get('variant_controls')
 if not isinstance(control,dict) or not control.get('source_id'):raise ValueError('source-backed variant controller required')
 for k in ('ego_speed_mps','target_speed_mps','ego_target_lateral_m'):number(control.get(k))
 if control['ego_speed_mps']<=0 or control['target_speed_mps']<=0 or (passed and control['ego_speed_mps']<=control['target_speed_mps']) or (not passed and control['ego_speed_mps']>control['target_speed_mps']):raise ValueError('source speeds cannot realize exact pass variant')
 lateral=control['ego_target_lateral_m'];paved_right=min(row['paved_y_bounds_m'][1] for row in sections)
 if passed and lateral-half<target_right:raise ValueError('right-side overtaking corridor absent')
 if off and lateral+half<=paved_right:raise ValueError('off-pavement target remains on pavement')
 if not off and lateral+half>paved_right:raise ValueError('on-pavement target crosses paved edge')
 spawn=site.get('native_spawn')
 if not isinstance(spawn,dict):raise ValueError('two source-backed Native poses required')
 for role in ('ego','target'):
  item=spawn.get(role)
  if not isinstance(item,dict) or not item.get('source_id') or not item.get('blueprint_id') or not isinstance(item.get('pose_xyz_ypr'),list) or len(item['pose_xyz_ypr'])!=6:raise ValueError('source-backed vehicle pose required: '+role)
  for v in item['pose_xyz_ypr']:number(v)
 return {'variant':suffix,'case_id':case,'ego_speed_mps':control['ego_speed_mps'],'target_speed_mps':control['target_speed_mps'],'ego_target_lateral_m':control['ego_target_lateral_m'],'expected_pass':passed,'expected_off_pavement':off,'zero_clearance_fit':fit,'native_readback_required':True}
def spawn_native(world,blueprints,site,request,transform_factory):
 actors={}
 try:
  for role in ('ego','target'):
   item=site['native_spawn'][role]
   actor=world.try_spawn_actor(blueprints.find(item['blueprint_id']),transform_factory(item['pose_xyz_ypr']))
   if actor is None or not getattr(actor,'id',None) or actor.get_transform() is None:raise ValueError('Native '+role+' spawn/readback failed')
   actors[role]=actor
  if actors['ego'].id==actors['target'].id:raise ValueError('distinct actor identities required')
  return actors
 except Exception:
  for actor in reversed(list(actors.values())):actor.destroy()
  raise
